class AuthCredentials(BaseModel):
    username: str = Field(min_length=3, max_length=64, pattern=r'^[A-Za-z0-9_.-]+$')
    password: str = Field(min_length=12, max_length=256)

def _read_users():
    if not AUTH_USERS_FILE.exists():
        return {}
    try:
        data = json.loads(AUTH_USERS_FILE.read_text(encoding='utf-8'))
    except (OSError, json.JSONDecodeError) as exc:
        raise RuntimeError('Authentication user store is unreadable') from exc
    if not isinstance(data, dict) or data.get('schema_version') != 1 or not isinstance(data.get('users'), dict):
        raise RuntimeError('Authentication user store has an unsupported schema')
    for username, record in data['users'].items():
        if not isinstance(username, str) or not isinstance(record, dict) or set(record) != {'salt', 'password_hash'}:
            raise RuntimeError('Authentication user store contains an invalid user record')
        try:
            salt = bytes.fromhex(record['salt'])
            password_hash = bytes.fromhex(record['password_hash'])
        except (TypeError, ValueError) as exc:
            raise RuntimeError('Authentication user store contains an invalid credential hash') from exc
        if len(salt) != 16 or len(password_hash) != 32:
            raise RuntimeError('Authentication user store contains an invalid credential hash')
    return data['users']

def _load_or_create_signing_key():
    configured = os.environ.get('JWT_SECRET_KEY')
    if configured:
        if len(configured.encode('utf-8')) < 32:
            raise RuntimeError('JWT_SECRET_KEY must contain at least 32 bytes')
        return configured
    AUTH_DATA_DIR.mkdir(parents=True, exist_ok=True)
    try:
        key = AUTH_SECRET_FILE.read_text(encoding='ascii').strip()
    except FileNotFoundError:
        generated = secrets.token_urlsafe(48)
        try:
            descriptor = os.open(AUTH_SECRET_FILE, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError:
            key = AUTH_SECRET_FILE.read_text(encoding='ascii').strip()
        else:
            with os.fdopen(descriptor, 'w', encoding='ascii') as handle:
                handle.write(generated)
                handle.flush()
                os.fsync(handle.fileno())
            key = generated
    if len(key.encode('ascii')) < 32:
        raise RuntimeError('Persisted JWT signing key is invalid')
    return key

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail='Bearer token required', headers={'WWW-Authenticate': 'Bearer'})
    scheme, _, token = authorization.partition(' ')
    if scheme.lower() != 'bearer' or not token:
        raise HTTPException(status_code=401, detail='Bearer token required', headers={'WWW-Authenticate': 'Bearer'})
    try:
        header_part, payload_part, signature_part = token.split('.')
        header = json.loads(_b64decode(header_part))
        if header != {'alg': 'HS256', 'typ': 'JWT'}:
            raise ValueError('unsupported token header')
        signing_input = f'{header_part}.{payload_part}'
        expected = hmac.new(jwt_secret.encode(), signing_input.encode(), hashlib.sha256).digest()
        if not hmac.compare_digest(expected, _b64decode(signature_part)):
            raise ValueError('invalid signature')
        claims = json.loads(_b64decode(payload_part))
        if int(claims['exp']) <= int(time.time()) or claims['sub'] not in users:
            raise ValueError('expired or unknown user')
        return claims['sub']
    except (ValueError, TypeError, KeyError, json.JSONDecodeError, binascii.Error):
        raise HTTPException(status_code=401, detail='Invalid bearer token', headers={'WWW-Authenticate': 'Bearer'})

