@app.post('/register')
def register(credentials: AuthCredentials):
    username = credentials.username.strip().lower()
    if not username:
        raise HTTPException(status_code=422, detail='Username is required')
    with _auth_lock:
        if username in users:
            raise HTTPException(status_code=409, detail='User already exists')
        salt = secrets.token_bytes(16)
        password_hash = hashlib.pbkdf2_hmac('sha256', credentials.password.encode('utf-8'), salt, 310000)
        users[username] = {'salt': salt.hex(), 'password_hash': password_hash.hex()}
        try:
            _write_users()
        except OSError as exc:
            users.pop(username, None)
            raise HTTPException(status_code=503, detail='Authentication storage is unavailable') from exc
    return {'success': True}

@app.post('/login')
def login(credentials: AuthCredentials):
    username = credentials.username.strip().lower()
    with _auth_lock:
        user = users.get(username)
        if not user:
            raise HTTPException(status_code=401, detail='Invalid credentials')
        salt = bytes.fromhex(user['salt'])
        password_hash = hashlib.pbkdf2_hmac('sha256', credentials.password.encode('utf-8'), salt, 310000).hex()
        if not hmac.compare_digest(password_hash, user['password_hash']):
            raise HTTPException(status_code=401, detail='Invalid credentials')
        token = _issue_token(username)
    return {'access_token': token, 'token_type': 'bearer'}

@app.get('/me')
def get_me(current_user: str = Depends(get_current_user)):
    return {'username': current_user}
